  ('m13-t1-p01', '{"tests":[{"label":"Sample Case","expectedStdout":"Data Science"},{"label":"notes.txt was created","assertCode":"assert __import__(\"os\").path.exists(\"notes.txt\"), \"Expected notes.txt to exist after your code runs\""},{"label":"file holds the right text","assertCode":"assert (open(\"notes.txt\").read()) == (\"Data Science\"), \"Expected \" + repr(\"Data Science\") + \", got \" + repr(open(\"notes.txt\").read())"}]}'::jsonb),
  ('m13-t1-p02', '{"tests":[{"label":"Sample Case","expectedStdout":"2"},{"label":"both lines are in the file","assertCode":"assert (open(\"log.txt\").read().splitlines()) == ([\"start\", \"end\"]), \"Expected \" + repr([\"start\", \"end\"]) + \", got \" + repr(open(\"log.txt\").read().splitlines())"},{"label":"append mode kept the first line","assertCode":"assert open(\"log.txt\").read().startswith(\"start\"), \"Mode \\\"a\\\" must append — \\\"w\\\" would have erased the first line\""}]}'::jsonb),
  ('m13-t1-p03', '{"tests":[{"label":"Sample Case","expectedStdout":"Chennai"},{"label":"three cities were written","assertCode":"assert (len(open(\"cities.txt\").read().splitlines())) == (3), \"Expected \" + repr(3) + \", got \" + repr(len(open(\"cities.txt\").read().splitlines()))"},{"label":"second city is Chennai","assertCode":"assert (open(\"cities.txt\").read().splitlines()[1]) == (\"Chennai\"), \"Expected \" + repr(\"Chennai\") + \", got \" + repr(open(\"cities.txt\").read().splitlines()[1])"}]}'::jsonb),
  ('m13-t1-p04', '{"tests":[{"label":"Sample Case","expectedStdout":"100"},{"label":"total is the sum of the column","assertCode":"assert (total) == (100), \"Expected \" + repr(100) + \", got \" + repr(total)"},{"label":"total has the right type","assertCode":"assert \"total\" in globals(), \"Expected a variable named total\"\nassert isinstance(total, int), \"Expected total to be int, got \" + type(total).__name__"},{"label":"the CSV still has a header plus two rows","assertCode":"assert (len(open(\"sales.csv\").read().splitlines())) == (3), \"Expected \" + repr(3) + \", got \" + repr(len(open(\"sales.csv\").read().splitlines()))"}]}'::jsonb),
