  ('m17-t3-p02', '{"tests":[{"label":"Sample Case","expectedStdout":"-1.0"},{"label":"correlation is -1.0","assertCode":"assert (round(float(np.corrcoef(a, b)[0, 1]), 2)) == (-1.0), \"Expected \" + repr(-1.0) + \", got \" + repr(round(float(np.corrcoef(a, b)[0, 1]), 2))"},{"label":"the strength is still perfect","assertCode":"assert abs(float(np.corrcoef(a, b)[0, 1])) == 1.0, \"The magnitude should be 1 even though the sign is negative\""}]}'::jsonb),
  ('m17-t3-p03', '{"tests":[{"label":"Sample Case","expectedStdout":"0.99"},{"label":"correlation is 0.99","assertCode":"assert (round(float(np.corrcoef(units, revenue)[0, 1]), 2)) == (0.99), \"Expected \" + repr(0.99) + \", got \" + repr(round(float(np.corrcoef(units, revenue)[0, 1]), 2))"},{"label":"it is strong but not perfect","assertCode":"assert float(np.corrcoef(units, revenue)[0, 1]) < 1.0, \"Real data should fall just short of a perfect 1.0\""}]}'::jsonb),
  ('m17-t3-p04', '{"tests":[{"label":"Sample Case","expectedStdout":"-0.91"},{"label":"correlation is -0.91","assertCode":"assert (round(float(np.corrcoef(price, demand)[0, 1]), 2)) == (-0.91), \"Expected \" + repr(-0.91) + \", got \" + repr(round(float(np.corrcoef(price, demand)[0, 1]), 2))"},{"label":"the relationship is negative","assertCode":"assert float(np.corrcoef(price, demand)[0, 1]) < 0, \"Demand falls as price rises, so the correlation must be negative\""}]}'::jsonb),
  ('m17-t3-p05', '{"tests":[{"label":"Sample Case","expectedStdout":"16.75"},{"label":"covariance is 16.75","assertCode":"assert (round(float(np.cov(units, revenue)[0, 1]), 2)) == (16.75), \"Expected \" + repr(16.75) + \", got \" + repr(round(float(np.cov(units, revenue)[0, 1]), 2))"},{"label":"covariance and correlation agree on direction","assertCode":"assert float(np.cov(units, revenue)[0, 1]) > 0 and float(np.corrcoef(units, revenue)[0, 1]) > 0, \"Both should be positive for this data\""}]}'::jsonb),
  ('m17-t3-p06', '{"tests":[{"label":"Sample Case","expectedStdout":"0.99"},{"label":"correlation from the frame","assertCode":"assert (round(float(df.corr().loc[\"units\", \"revenue\"]), 2)) == (0.99), \"Expected \" + repr(0.99) + \", got \" + repr(round(float(df.corr().loc[\"units\", \"revenue\"]), 2))"},{"label":"a column correlates perfectly with itself","assertCode":"assert (round(float(df.corr().loc[\"units\", \"units\"]), 2)) == (1.0), \"Expected \" + repr(1.0) + \", got \" + repr(round(float(df.corr().loc[\"units\", \"units\"]), 2))"}]}'::jsonb),
  ('m17-t3-p07', '{"tests":[{"label":"Sample Case","expectedStdout":"[[1.0, 0.99], [0.99, 1.0]]\nstrong"},{"label":"verdict is strong","assertCode":"assert (verdict) == (\"strong\"), \"Expected \" + repr(\"strong\") + \", got \" + repr(verdict)"},{"label":"matrix rounds as expected","assertCode":"assert (np.round(matrix.values, 2).tolist()) == ([[1.0, 0.99], [0.99, 1.0]]), \"Expected \" + repr([[1.0, 0.99], [0.99, 1.0]]) + \", got \" + repr(np.round(matrix.values, 2).tolist())"},{"label":"the diagonal is 1.0","assertCode":"assert abs(float(matrix.iloc[0, 0]) - 1.0) < 1e-9, \"Every column correlates perfectly with itself\""}]}'::jsonb),
  ('m17-t4-p01', '{"tests":[{"label":"Sample Case","expectedStdout":"22.5\n15.5"},{"label":"mean is dragged up","assertCode":"assert (float(np.mean(orders))) == (22.5), \"Expected \" + repr(22.5) + \", got \" + repr(float(np.mean(orders)))"},{"label":"median stays central","assertCode":"assert (float(np.median(orders))) == (15.5), \"Expected \" + repr(15.5) + \", got \" + repr(float(np.median(orders)))"},{"label":"the mean sits above the median","assertCode":"assert float(np.mean(orders)) > float(np.median(orders)), \"The outlier should pull the mean above the median\""}]}'::jsonb),
  ('m17-t4-p02', '{"tests":[{"label":"Sample Case","expectedStdout":"9.38\n22.38"},{"label":"lower fence","assertCode":"assert (round(float(lower), 2)) == (9.38), \"Expected \" + repr(9.38) + \", got \" + repr(round(float(lower), 2))"},{"label":"upper fence","assertCode":"assert (round(float(upper), 2)) == (22.38), \"Expected \" + repr(22.38) + \", got \" + repr(round(float(upper), 2))"},{"label":"the fences come from the IQR","assertCode":"assert float(upper) > float(lower), \"The upper fence must sit above the lower fence\""}]}'::jsonb),
  ('m17-t4-p03', '{"tests":[{"label":"Sample Case","expectedStdout":"[12, 14, 15, 16, 18]"},{"label":"the outlier is gone","assertCode":"assert (clean) == ([12, 14, 15, 16, 18]), \"Expected \" + repr([12, 14, 15, 16, 18]) + \", got \" + repr(clean)"},{"label":"60 was excluded","assertCode":"assert 60 not in clean, \"The 60 order sits outside the fences and should be dropped\""},{"label":"the source list is unchanged","assertCode":"assert (len(orders)) == (6), \"Expected \" + repr(6) + \", got \" + repr(len(orders))"}]}'::jsonb),
