  ('m17-t4-p05', '{"tests":[{"label":"Sample Case","expectedStdout":"2.22"},{"label":"largest z-score","assertCode":"assert (round(float(z.max()), 2)) == (2.22), \"Expected \" + repr(2.22) + \", got \" + repr(round(float(z.max()), 2))"},{"label":"the z-scores average to zero","assertCode":"assert abs(float(z.mean())) < 1e-9, \"Z-scores are centred, so their mean must be 0\""},{"label":"the largest z-score belongs to the 60","assertCode":"assert int(np.argmax(z)) == 5, \"The biggest order should have the highest z-score\""}]}'::jsonb),
